SELECT id, device_code, reading_ts, temp_c, status_bits, LAST_VALUE(temp_c, TRUE) OVER (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_temp_c, FIRST_VALUE(temp_c) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c, SUM(humidity) OVER (PARTITION BY device_code) AS device_code_sum_humidity FROM device_readings;
